Example: Cloning an Objectclass Student implements Cloneable {
	int id;
	String name;
	Student(int id, String name) {
		this.id = id;
		this.name = name;
	}
	// Overriding clone() method
	public Object clone() throws CloneNotSupportedException {
		return super.clone();
	}
}
public class Main {
	public static void main(String[] args) {
		try {
			Student s1 = new Student(101, "Jack");
			Student s2 = (Student) s1.clone();
			System.out.println("Original Student Object: " + s1.id + " - " + s1.name);
			System.out.println("Cloned Student Object: " + s2.id + " - " + s2.name);
			// Modifying cloned object
			s2.name = "Smith";
			System.out.println("\nAfter modifying cloned object:");
			System.out.println("Original Student Object: " + s1.id + " - " + s1.name);
			System.out.println("Cloned Student Object: " + s2.id + " - " + s2.name);
		} catch (CloneNotSupportedException e) {
			e.printStackTrace();
		}
	}
}
